        self.todos: Dict[int, Dict] = {}  # Todo ID -> Todo Object
        # Next todo ID to assign (starts from 1)
        self.next_todo_id = 1
        # Track completed todos count
        self.completed_count = 0
        # Thread lock for safety
        self.lock = threading.Lock()
        # Rate limit tracking per team
        self.request_count = 0
        self.rate_limit_window = 0
        self.rate_limit_expiry = None

teams: Dict[str, TeamData] = {}  # Team ID -> TeamData
teams_lock = threading.Lock()
rate_limits: Dict[str, list] = defaultdict(list)  # Team ID -> request timestamps
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100  # Requests per minute
RATE_LIMIT_WINDOW = 60  # seconds

# SQL injection pattern detection - reject suspicious patterns
# Keywords that indicate SQL injection attempts
SQL_INJECTION_KEYWORDS = re.compile(
    r"(DROP|CREATE|ALTER|DELETE|UPDATE|INSERT|SELECT|UNION|OR|AND|'|--|;--|--|--)",
    re.IGNORECASE
)

def _check_rate_limit(team_id: str) -> bool:
    """Check if team rate limit exceeded. Returns True if limit exceeded."""
    with rate_limit_lock:
        # Get current timestamp
        current_time = datetime.now(timezone.utc)

        # Check rate limit history for this team
        team_requests = rate_limits.get(team_id, [])

        # Filter out requests outside the last minute window
        window_start = current_time - timedelta(seconds=RATE_LIMIT_WINDOW)
        relevant_requests = [ts for ts in team_requests if ts > window_start]

        # If requests in window >= limit, rate limited
        if len(relevant_requests) >= RATE_LIMIT:
            # Record current request
            with rate_limit_lock:
                team_requests.append(current_time.isoformat())
                # Clean old entries
                while len(team_requests) > RATE_LIMIT:
                    team_requests.pop(0)
            return True

        return False

def _validate_team_id(team_id: str) -> bool:
    """Validate team ID exists and is proper format."""
    with teams_lock:
        return team_id in teams

def _get_team(team_id: str) -> Optional[TeamData]:
    """Get team by ID."""
    with teams_lock:
        # Validate team ID format (must be string, not int)
        if not isinstance(team_id, str):
            return None
        return teams.get(team_id)

def _validate_todo_data(data: dict) -> Optional[str]:
    """Validate todo creation data. Returns error message if invalid."""
    if not data or not isinstance(data, dict):
        return "Missing required fields"

    # Check for SQL injection patterns in title
    title = data.get('title', '')
    if SQL_INJECTION_KEYWORDS.search(title):
        return "Invalid title - contains SQL injection pattern"

    # Check title length (max 1000 characters)
    if len(title) > 1000:
        return "Title exceeds maximum length of 1000 characters"

    # Check missing title field
    if not data.get('title'):
        return "Title is required"

    # Check empty title
    if title.strip() == "":
        return "Title cannot be empty"

    return None

def _deep_copy_todo(todo: Dict) -> Dict:
