@app.route('/teams', methods=['POST'])
def create_team():
    """Create a new team."""
    # Parse JSON body
    data = request.get_json(force=True)

    if not data:
        return jsonify({"error": "Invalid JSON"}), 400

    # Validate required fields: name and capacity
    name = data.get('name')
    capacity = data.get('capacity')

    # Check for SQL injection in name
    if SQL_INJECTION_KEYWORDS.search(str(name)):
        return jsonify({"error": "Invalid title - contains SQL injection pattern"}), 400

    # Validate name is not empty after trimming
    if not name or not name.strip():
        return jsonify({"error": "Missing or empty name"}), 400

    # Validate capacity - must be positive integer
    if capacity is None:
        return jsonify({"error": "Missing required field: capacity"}), 400

    # Check capacity type - must be integer
    if not isinstance(capacity, int) or capacity <= 0:
        return jsonify({"error": "Invalid capacity - must be positive integer"}), 400

    # Create team
    with teams_lock:
        team = TeamData(name=name.strip(), capacity=capacity)
        teams[team.id] = team

    # Return proper response format
    response = {
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }
    return jsonify(response), 201

