    # Get todos for this team
    with teams_lock:
        team_todos = list(team.todos.values())

    # Calculate statistics
    total_todos = len(team_todos)
    completed_count = sum(1 for todo in team_todos if todo.get("completed", False))

    # Calculate capacity used percentage (format: "X.X%")
    # Requirement: "capacity_used": "0.0%" (string format with percentage sign)
    # For no todos case: "0.0%"

    if total_todos == 0:
        capacity_used = "0.0%"
    else:
        # Calculate percentage based on completed vs total
        # Format: f"{value:.1f}%"
        capacity_used = f"{(completed_count / max(1, total_todos)) * 100:.1f}%"

    # Response format
    response = {
        "total_todos": total_todos,
        "completed": completed_count,
        "capacity_used": capacity_used
    }

