@app.route('/todos', methods=['GET'])
def get_todos():
    """List all todos for current team with pagination and filtering."""
    # Check authorization
    team_id = request.headers.get('X-Team-ID')
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Validate team exists
    team = _get_team(team_id)
    if not team:
        return jsonify({
            "error": "Team not found"
        }), 404

    # Get query parameters
    page = request.args.get('page', '1')
    page_size = request.args.get('page_size', '50').strip()
    filter_completed = request.args.get('completed')
    filter_tag = request.args.get('tag')
    sort = request.args.get('sort')

    # Validate page number
    try:
        page_int = int(page)
        if page_int < 1:
            return jsonify({
                "error": "Invalid page number"
            }), 400
    except ValueError:
        return jsonify({
            "error": "Invalid page number"
        }), 400

    # Validate page size
    try:
        page_size_int = int(page_size)
        if page_size_int > 50:
            page_size = 50  # Maximum page size
        elif page_size_int <= 0:
            page_size = 50
        else:
            page_size = page_size_int
    except ValueError:
        return jsonify({
            "error": "Invalid page size"
        }), 400

    # Filter todos
    all_todos = []
    team_todos_list = list(team.todos.values())

    # Apply filters
    if filter_completed is not None:
        # Filter by completed status
        if filter_completed == "true":
            all_todos = [todo for todo in team_todos_list if todo.get("completed", False)]
        elif filter_completed == "false":
            all_todos = [todo for todo in team_todos_list if not todo.get("completed", False)]
        else:
            all_todos = []

    if filter_tag:
        # Filter by tag - todo must have tag in its tags array
        tag_lower = filter_tag.lower()
        all_todos = [todo for todo in all_todos if any(tag_lower in t.lower() for tag in todo.get("tags", []))]

    # Sort options
    if sort == 'created_asc':
        # Default: oldest first by creation time
        all_todos.sort(key=lambda x: x.get("created_at", ""))
    elif sort == 'created_desc':
        # Newest first
        all_todos.sort(key=lambda x: x.get("created_at", ""), reverse=True)
    elif sort == 'title':
        # Alphabetical by title
        all_todos.sort(key=lambda x: x.get("title", ""))
    else:
        # Invalid sort - return all without sorting
        pass

    # Pagination
    # Convert page string to int
    try:
        page_num = int(page)
    except ValueError:
        return jsonify({
            "error": "Invalid page number"
        }), 400

    # Calculate total count
    total_count = len(all_todos)

    # Calculate pagination
    per_page = page_size if page_size <= 50 else 50
    start_idx = (page_num - 1) * per_page
    end_idx = start_idx + per_page

    # Slice todos for current page
    page_todos = all_todos[start_idx:end_idx]

    # Build response
    response = {
        "todos": [todo.copy() for todo in page_todos],
        "page": page_num,
        "page_size": per_page,
        "next_cursor": None if end_idx >= total_count else f"page_{page_num + 1}",
        "total": total_count
    }

    return jsonify(response), 200

