def update_todo(todo_id: int):
    """Update specific todo by ID."""
    # Check authorization
    team_id = request.headers.get('X-Team-ID')
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Validate team exists
    team = _get_team(team_id)
    if not team:
        return jsonify({
            "error": "Team not found"
        }), 404

    # Check X-If-Version header (mandatory)
    version_header = request.headers.get('X-If-Version')
    if not version_header:
        return jsonify({
            "error": "Missing required header: X-If-Version"
        }), 400

    # Validate version is numeric
    try:
        version_int = int(version_header)
    except ValueError:
        return jsonify({
            "error": "Invalid version format"
        }), 400

    # Check version conflict (optimistic concurrency control)
    # Get current version of todo
    todo = None
    for todo_data in team.todos.values():
        if todo_data.get("id") == todo_id:
            todo = todo_data
            break

    if not todo:
        # Todo not found - version mismatch
        return jsonify({
            "error": "Version mismatch",
            "current_version": 1,
            "provided_version": int(version_header)
        }), 409

    # Current version matches provided version - update allowed
    # Update todo data
    # Update fields only if provided
    todo["version"] = version_int + 1
    todo["updated_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    # Update team's todos dictionary
    with teams_lock:
        team.todos[todo_id] = todo

    # Return updated todo
    response = todo.copy()
    response["version"] = todo["version"]
    response["updated_at"] = todo["updated_at"]

    return jsonify(response), 200

