@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    """Batch update multiple todos."""
    # Check authorization
    team_id = request.headers.get('X-Team-ID')
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Validate team exists
    team = _get_team(team_id)
    if not team:
        return jsonify({
            "error": "Team not found"
        }), 404

    # Parse request body
    data = request.get_json(force=True)

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Invalid request body"}), 400

    # Check required 'updates' field
    if 'updates' not in data:
        return jsonify({"error": "Missing required field: updates"}), 400

    updates = data['updates']

    # Validate updates structure
    if not isinstance(updates, list):
        return jsonify({"error": "Updates must be an array"}), 400

    # Maximum 100 updates
    if len(updates) > 100:
        return jsonify({"error": "Maximum 100 updates per batch"}), 400

    # Process each update
    updated_todos = []
    todo_updates = {}  # Map todo_id -> update info

    valid_updates = []
    invalid_update_reasons = []

    for update_item in updates:
        # Update item must be an object/dict
        if not isinstance(update_item, dict):
            invalid_update_reasons.append(f"Update item must be object, got {type(update_item).__name__}")
            continue

        # Update item must have 'id' field
        if 'id' not in update_item:
            invalid_update_reasons.append("Update item missing 'id' field")
            continue

        todo_id = update_item['id']

        # Validate todo exists (atomic failure - all or nothing)
        # Check if todo exists in current team's todos
        todo_exists = False
        for existing_todo_id, existing_todo in team.todos.items():
            if existing_todo_id == todo_id:
                todo_exists = True
                break

        if not todo_exists:
            # Todo doesn't exist - entire batch fails
            invalid_update_reasons.append(f"Todo ID {todo_id} not found")
            continue

        # Validate update fields
        title = update_item.get('title')
        if title is None or not title or title.strip() == "":
            invalid_update_reasons.append("Update title is required")
            continue

        # Check title length
        if len(title) > 1000:
            invalid_update_reasons.append("Title exceeds maximum length")
            continue

        # Update the todo
        todo = team.todos[todo_id]
        # Update only provided fields
        todo["title"] = title
        todo["updated_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

        # Increment version
        todo["version"] = todo["version"] + 1

        # Add to updated list
        updated_todos.append({
            "id": todo_id,
            "title": title,
            "version": todo["version"]
        })
        valid_updates.append(True)

    # Atomic failure: if any update failed, reject entire batch
    if invalid_update_reasons:
        return jsonify({
            "error": "Batch update failed",
            "message": "; ".join(invalid_update_reasons)
        }), 400

    # Return successful update response
    response = {
        "updated": updated_todos,
        "count": len(updated_todos)
    }

    return jsonify(response), 200

